// Writes apps/worker/src/store/migrations.gen.ts from packages/db/{directory,budget,store}-migrations/*.sql, so the
// Durable Objects get their migrations as plain strings (no bundler rules) and tests load exactly what production
// does. `--check` fails if the generated file is out of date (run by tools/ci/migration-check.mjs).
import { readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { STORE_LAST_BUDGET } from './store-last-budget.mjs';

const OUT = 'apps/worker/src/store/migrations.gen.ts';
const read = (dir) =>
  readdirSync(dir)
    .filter((f) => f.endsWith('.sql'))
    .sort()
    .map((f) => ({ name: f, sql: readFileSync(`${dir}/${f}`, 'utf8') }));

const body =
  `// Generated by tools/db/gen-store-migrations.mjs from packages/db/{directory,budget,store}-migrations. Do not edit.\n` +
  `export interface StoreMigration {\n  name: string;\n  sql: string;\n}\n\n` +
  `export const DIRECTORY_MIGRATIONS: StoreMigration[] = ${JSON.stringify(read('packages/db/directory-migrations'), null, 2)};\n\n` +
  `export const BUDGET_MIGRATIONS: StoreMigration[] = ${JSON.stringify(read('packages/db/budget-migrations'), null, 2)};\n\n` +
  // Named apart from the budget's ("store/0001_..."): both lists are recorded in one _migrations table.
  `/** Tables only the server's BudgetStore keeps (docs/privacy.md 5.3): a phone's copy never runs these. */\n` +
  `export const STORE_MIGRATIONS: StoreMigration[] = ${JSON.stringify(
    read('packages/db/store-migrations').map((m) => ({ ...m, name: `store/${m.name}` })),
    null,
    2,
  )};\n\n` +
  `/** The last budget migration a BudgetStore runs (D-106): later ones run on the devices' copies only. */\n` +
  `export const STORE_LAST_BUDGET_MIGRATION = ${JSON.stringify(STORE_LAST_BUDGET)};\n\n` +
  `/** What a BudgetStore runs: the budget's migrations up to STORE_LAST_BUDGET_MIGRATION, then its own. */\n` +
  `export const BUDGET_STORE_MIGRATIONS: StoreMigration[] = [\n` +
  `  ...BUDGET_MIGRATIONS.filter((m) => m.name <= STORE_LAST_BUDGET_MIGRATION),\n` +
  `  ...STORE_MIGRATIONS,\n` +
  `];\n`;

if (process.argv.includes('--check')) {
  let cur = '';
  try {
    cur = readFileSync(OUT, 'utf8');
  } catch {
    // missing counts as out of date
  }
  if (cur !== body) {
    console.error(`${OUT} is out of date: run node tools/db/gen-store-migrations.mjs`);
    process.exit(1);
  }
  console.log('store migrations: generated file is current');
} else {
  writeFileSync(OUT, body);
  console.log(`wrote ${OUT}`);
}
